python3 -c "
import json
with open('/app/resources/treasury_bulletin_2000_06.json', 'r') as f:
    data = json.load(f)
doc = data['document']
print('document keys:', doc.keys())
for k, v in doc.items():
    if isinstance(v, dict):
        print(f'  {k} keys: {list(v.keys())[:10]}')
    elif isinstance(v, list):
        print(f'  {k}: list of {len(v)} items')
        if len(v) > 0:
            print(f'    first item type: {type(v[0])}')
            if isinstance(v[0], dict):
                print(f'    first item keys: {list(v[0].keys())[:10]}')
"
